-- ============================================================
-- AxysEasy — Schema SQL
-- Banco: PostgreSQL 14+
-- Schemas: catalogo · audit · ativo · tenant_catalogo · arquivo
--
-- catalogo   : catálogo de fontes de preços, insumos, preços por
--         edição/UF/modalidade, composições de preço versionadas
--         e hierarquia de grupos/subgrupos.
-- audit : trilha de auditoria — quem/quando/o quê/antes/depois.
-- ativo : módulo Ativo — orçamento (árvore), ficha, BDI/LS, cronograma,
--         memória de cálculo, revisões, drivers e diversidades. Ver bloco
--         "MÓDULO ATIVO" no fim deste arquivo.
-- tenant_catalogo : biblioteca técnica própria do tenant (insumos/composições).
-- arquivo : registro de desconstrução/reconstrução por tenant (offboarding).
--
-- Decisões de arquitetura
-- ───────────────────────
-- VERSIONAMENTO DE CATÁLOGO (FASE 2)
--   insumos E composicoes são a IDENTIDADE VIGENTE por (fonte, código): 1 linha,
--   atributos cadastrais (descrição/unidade/situação) = estado vigente. A SÉRIE por
--   edição vive nas densas: insumos_preco (insumo) e composicoes_custo (cc_edi_id).
--   A EVOLUÇÃO cadastral/estrutural vai p/ *_historico (snapshot na mudança).
--   UNIQUE: composições (cmp_fte_id, cmp_codigo); insumos (ins_fte_id, ins_codigo).
--   composicoes_itens = RECEITA VIGENTE (ci_cmp_id → identidade). Re-import de edição
--   nova = get-or-create identidade + replace da receita vigente + upsert custo@edição.
--
-- UF / MODALIDADE
--   insumos_preco e composicoes_custo armazenam uma linha por
--   (insumo/composição, edição, uf, modalidade).
--   SINAPI: todas 27 UFs importadas por edição.
--   Estimativa: ~262 k linhas de preço de insumo por import (× 3 modalidades);
--   ~560 k de custo de composição (× 3 modalidades). PostgreSQL suporta com folga.
--   modalidade: 'SD' = sem desoneração | 'CD' = com desoneração | 'SE' = sem encargos sociais
--
-- TENANCY
--   Tabelas catalogo.*: catálogo compartilhado — sem tenant_uuid.
--   Dados do tenant (futuro módulo "ativo") carregarão tenant_uuid
--   quando implementados — fora deste schema por ora.
--
-- GRUPOS / SUBGRUPOS
--   catalogo.composicoes_grupos:    nível 1 (CDHU: código 'XX'; SINAPI: não usa)
--   catalogo.composicoes_subgrupos: nível 2 — sub_grp_id NULLABLE para SINAPI
--     (SINAPI usa sub_grp_id = NULL; seus "grupos" são subgrupos)
--
-- TIPO DE INSUMO
--   ins_tipo_sinapi: classificação exata da fonte (SINAPI verbatim
--     ou mapeado de outras fontes). Fidelidade ao dado original.
--   ins_ti_id: FK para catalogo.insumos_tipo
--     (MO / EQUIP_AQ / EQUIP_LOC / MAT / SERV / ESP)
--     agrupamento para histogramas e relatórios.
--   Mapeamento padrão SINAPI → insumos_tipo:
--     MATERIAL                → MAT
--     MAO DE OBRA             → MO
--     ENCARGOS COMPLEMENTARES → MO
--     EQUIPAMENTO (AQUISIÇÃO) → EQUIP_AQ
--     EQUIPAMENTO (LOCAÇÃO)   → EQUIP_LOC
--     SERVIÇOS                → SERV
--     ESPECIAIS               → ESP
--
-- PADRÃO DE NOMENCLATURA
--   Prefixo de coluna = abreviatura da tabela
--   PKs: IDENTITY (GENERATED BY DEFAULT); tabelas de volume usam BIGINT (insumos, composicoes, insumos_preco, composicoes_custo, composicoes_itens)
--   Timestamps: TIMESTAMPTZ; datas: DATE
--   Coeficientes: NUMERIC(14,10) (CDHU usa 4 casas, SINAPI 7); preços/valores: NUMERIC(14,4)
--   Audit trail: _criado_em, _atualizado_em, _criado_por, _atualizado_por
--
-- ESTRUTURA RECOMENDADA / CONTRATO INTERNO DA APP
-- Estes JSONB são gerados exclusivamente pela aplicação.
-- Não devem ser montados livremente por usuários, integrações externas
-- ou rotinas ad hoc.
-- A estrutura pode evoluir, mas somente por alteração deliberada da app,
-- com compatibilidade documentada e, quando necessário, versionamento.
-- Qualquer alteração estrutural nestes JSONB deve ser tratada como
-- mudança de contrato interno da aplicação.
--
-- DOCUMENTAÇÃO EXTERNA (JSONB) — `ins_external_path` / `cmp_external_path`.
--   Guardam SÓ paths, na IDENTIDADE, com VIGÊNCIA POR VERSÃO. Spec canônica nos
--   comentários das próprias colunas + publicacao.md §11.10:
--     { <tipo>: { "fonte":..., "versoes":[ {"desde_edi":E, "path":...} ] } }
--   ficha_tecnica (insumo) · caderno_tecnico/ctc (composição). url derivada = /doc-file/ + path.
--
-- AUDITORIA (JSONB) — schema audit
--   audit.logs.log_dados_antes / log_dados_depois: snapshot do registro
--     afetado como objeto SIMPLES coluna→valor — NÃO embrulhar em
--     schema/tabela/pk (log_schema, log_tabela, log_registro_id e log_acao
--     já são colunas próprias). Cadastros: objeto completo; alta
--     frequência: diff parcial (só campos alterados).
--     Ex.: { "ins_descricao": "...", "ins_unidade": "UN", "ins_ti_id": 4 }
--   audit.api_logs.log_corpo_req: corpo da requisição (POST/PUT/PATCH/DELETE).
--     O conteúdo deve ser SANITIZADO antes da gravação. É VEDADO registrar
--     senha, token, segredo, chave privada, credenciais ou dados sensíveis.
--     Alteração estrutural deste JSONB = mudança de contrato interno da app.
--     Ex.: { "codigo": "45087", "descricao": "..." }
--   audit.login_logs.log_detalhes: metadados do evento de autenticação.
--     Ex.: { "motivo_falha": "senha_invalida", "tentativas": 3 }
--          | { "provider_sub": "...", "scopes": [...] }
--
--   Os JSONB de catalogo.insumos_historico e catalogo.composicoes_historico
--   têm ESTRUTURA RECOMENDADA (não contrato rígido) no comentário de cada tabela.
-- ============================================================


-- Silencia os NOTICE "does not exist, skipping" dos DROP IF EXISTS / DROP POLICY IF EXISTS
-- idempotentes quando o schema roda num banco NOVO (o objeto ainda não existe). Não é erro —
-- é ruído. WARNING e ERROR continuam visíveis. Assim o create fica limpo sem duplicar o schema.
SET client_min_messages = WARNING;


-- ============================================================
-- SCHEMA: catalogo
-- ============================================================

CREATE SCHEMA IF NOT EXISTS catalogo;

GRANT USAGE ON SCHEMA catalogo  TO "axys_tec";

ALTER DEFAULT PRIVILEGES IN SCHEMA catalogo
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO "axys_tec";

ALTER DEFAULT PRIVILEGES IN SCHEMA catalogo
    GRANT USAGE, SELECT ON SEQUENCES TO "axys_tec";

-- Extensões de busca textual (catalogo.search_document, ver §SEARCH / listagem.md).
-- Instaladas NO schema catalogo (este banco não tem 'public'); por isso os usos são
-- qualificados: catalogo.unaccent(...), catalogo.gin_trgm_ops, catalogo.similarity(...).
-- unaccent: remove acentos p/ normalização; pg_trgm: similaridade/fuzzy + GIN.
CREATE EXTENSION IF NOT EXISTS unaccent SCHEMA catalogo;
CREATE EXTENSION IF NOT EXISTS pg_trgm  SCHEMA catalogo;


-- ============================================================
-- TABELA: catalogo.insumos_tipo
-- Contrato de regra de negócio (canônico):
--   docs/projects/axys-easy/contracts/catalogo/imports/estagios.md
-- Grupos de insumos para histogramas e relatórios.
-- Domínio estrutural — seed inline logo abaixo (todos os seeds vivem no schema).
--
-- NC = "Não Classificado": fallback técnico CONTROLADO de curadoria, NÃO é
--   categoria técnica real da fonte. Existe p/ permitir import completo sem
--   abortar (ins_ti_id é NOT NULL). Entra em fila de curadoria e NÃO deve
--   alimentar histogramas gerenciais como tipo técnico normal.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.insumos_tipo (
    ti_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ti_codigo          TEXT    NOT NULL,   -- MO|ENC_COMP|EQUIP_AQ|EQUIP_LOC|MAT|SERV|ESP|NC
    ti_nome            TEXT    NOT NULL,
    ti_ativo           BOOLEAN NOT NULL DEFAULT TRUE,
    ti_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ti_atualizado_em   TIMESTAMPTZ,
    ti_criado_por      TEXT,
    ti_atualizado_por  TEXT,

    CONSTRAINT uq_insumos_tipo_codigo
        UNIQUE (ti_codigo),

    CONSTRAINT ck_insumos_tipo_codigo_vazio
        CHECK (btrim(ti_codigo) <> ''),

    CONSTRAINT ck_insumos_tipo_nome_vazio
        CHECK (btrim(ti_nome) <> '')
);

-- Seed estrutural — inline (NÃO há seed.sql separado: todos os seeds vivem
-- aqui no schema, aplicados pelo rebuild logo após o DDL).
INSERT INTO catalogo.insumos_tipo (ti_codigo, ti_nome, ti_criado_por)
SELECT v.codigo, v.nome, 'Axys — seed inicial'
FROM (VALUES
    ('MO',       'Mão de Obra'),
    ('ENC_COMP', 'Encargos Complementares'),
    ('EQUIP_AQ', 'Equipamento — Aquisição'),
    ('EQUIP_LOC','Equipamento — Locação'),
    ('MAT',      'Material'),
    ('SERV',     'Serviço'),
    ('ESP',      'Especiais'),
    ('NC',       'Não Classificado')
) AS v(codigo, nome)
ON CONFLICT (ti_codigo) DO NOTHING;


-- ============================================================
-- catalogo.situacoes — ⚠️ DROPADA 2026-07-14 (R3).
--   Era lookup p/ um enum pequeno/fixo. A situação de PREÇO virou insumos_preco.pri_situacao
--   TEXT CHECK ('COM PREÇO'|'SEM PREÇO'); composições já usavam cmp_situacao TEXT CHECK.
--   Removida da foto; a tabela viva é dropada no rebuild (DROP TABLE IF EXISTS catalogo.situacoes).
-- ============================================================


-- ============================================================
-- catalogo.unidades — VOCABULÁRIO CONTROLADO de unidades de grandeza.
-- Por que existe: import vem (quase) normalizado, mas a CRIAÇÃO MANUAL de
-- insumos/composições (fontes próprias, AXYS) geraria lixo/typos (m4, m5,
-- M2/MES × M2XMES...). Centraliza o vocabulário e dá integridade.
-- PK NATURAL = o próprio código (texto): o que fica gravado em
--   insumos.ins_unidade / composicoes.cmp_unidade é o código legível
--   ('M3','KG','UN','M3XKM') — NÃO um id surrogate (banco continua legível).
-- Contraste com situação: unidade é vocabulário grande/extensível → TABELA;
--   situação é enum pequeno/fixo → CHECK. (Princípio em BUSINESS_RULES §6/§8.2.)
-- Compostas existem (transporte/locação): M3XKM, TXKM, M2XMES → use TEXT
--   (não char(3/4)). Convenção canônica a fechar: maiúsculas, separador 'X'
--   p/ composta, sem acento ('MES') — normalizar variantes na Fase 2.
-- IDEIA FUTURA (não decidida): FK ins_unidade/cmp_unidade → unidades(un_codigo); criação
--   manual só da lista (+ "Outra" restrita a admin). Só com gatilho nomeado (ADR-022).
-- Seed abaixo = núcleo canônico; o restante o import popula/normaliza.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.unidades (
    un_codigo        TEXT PRIMARY KEY,   -- código natural legível; é o valor gravado nas FKs (sem surrogate)
    un_descricao     TEXT,               -- rótulo amigável (ex.: 'Metro cúbico') — pode ser preenchido depois
    un_categoria     TEXT,               -- hook p/ conversão (comprimento|area|volume|massa|tempo|composta|outro) — ver §9.5
    un_ativo         BOOLEAN NOT NULL DEFAULT TRUE,
    un_criado_em     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    un_atualizado_em TIMESTAMPTZ,
    un_criado_por    TEXT,
    un_atualizado_por TEXT,

    CONSTRAINT ck_unidades_codigo_vazio CHECK (btrim(un_codigo) <> '')
);

-- Seed = núcleo canônico (import upserta/normaliza o resto na Fase 2).
