-- CAIXA ALTA em TODAS as descrições de unidade (padrão de identidade do catálogo — feedback Renan).
UPDATE catalogo.unidades SET un_descricao = upper(un_descricao) WHERE un_descricao <> upper(un_descricao);


-- ============================================================
-- TABELA: catalogo.fontes
-- Contrato funcional (canônico):
--   docs/projects/axys-easy/contracts/catalogo/fontes.md
-- Catálogo das fontes de preços (SINAPI, CDHU, AXYS). A importação de outras
-- fontes será doutrinada via template (fora do escopo atual).
--
-- fte_ordem_edicao:
--   'DATA'   — edição mais recente = maior edi_mes_ref
--   'VERSAO' — edição mais recente = maior edi_codigo_versao
-- fte_tem_catalogo_insumos: publica fichas de insumo? (só SINAPI). Se TRUE, a edição
--   exige upload das fichas p/ publicar (BUSINESS_RULES §10).
-- fte_catalogos_continuos: docs (fichas/cadernos/critérios) contínuos — não mudam por
--   edição? SINAPI=TRUE (skip por data de atualização); CDHU=FALSE (reemite por edição);
--   AXYS=TRUE (app-own). Ver BUSINESS_RULES §11.
--
-- Fonte 'AXYS': composições próprias do tenant — sem edição
--   mensal; preço informado direto, sem linha em insumos_preco.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.fontes (
    fte_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fte_codigo         TEXT    NOT NULL,   -- 'SINAPI' | 'CDHU' | 'AXYS'
    fte_nome           TEXT    NOT NULL,
    fte_ordem_edicao   TEXT    NOT NULL DEFAULT 'DATA',
    fte_ativa          BOOLEAN NOT NULL DEFAULT TRUE,
    -- Governança de catálogo de documentos (R2) — ver BUSINESS_RULES §10/§11:
    fte_tem_catalogo_insumos BOOLEAN NOT NULL DEFAULT FALSE,  -- publica fichas de insumo? (só SINAPI). Se TRUE, edição exige upload das fichas p/ publicar.
    fte_tem_caderno_metodologia BOOLEAN NOT NULL DEFAULT FALSE, -- publica livro/caderno de metodologia (conceitos, instruções)? SINAPI=TRUE; CDHU=TRUE; AXYS=FALSE.
    fte_catalogos_continuos  BOOLEAN NOT NULL DEFAULT FALSE,  -- docs contínuos (não mudam por edição → skip por data)? SINAPI=TRUE; CDHU=FALSE (reemite por edição).
    -- Segurança/governança (ver BUSINESS_RULES §8.1): permite criar/editar insumos,
    -- composições e ajustes manuais NESTA fonte? Só fontes PRÓPRIAS (AXYS) = TRUE.
    -- Catálogos de terceiros (SINAPI/CDHU) = FALSE → imutáveis por qualquer usuário
    -- (risco alto). Esta flag é o GATE consumido pelas telas de insumos/composições.
    fte_permite_manipular_dados BOOLEAN NOT NULL DEFAULT FALSE,
    -- EXIBIÇÃO dos arquivos originais no caderno técnico da edição (seção "Arquivos originais",
    -- entre Dados e Encargos Sociais). É SÓ flag de VITRINE — NÃO define bucket público nem
    -- libera o blob: o armazenamento (public/private) é decidido no import, independente disto.
    -- TRUE só p/ fontes cujos originais são de divulgação: AXYS (própria) e SINAPI (público oficial).
    fte_public         BOOLEAN NOT NULL DEFAULT FALSE,
    fte_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fte_atualizado_em  TIMESTAMPTZ,
    fte_criado_por     TEXT,
    fte_atualizado_por TEXT,

    CONSTRAINT uq_fontes_codigo
        UNIQUE (fte_codigo),

    CONSTRAINT ck_fontes_codigo_vazio
        CHECK (btrim(fte_codigo) <> ''),

    CONSTRAINT ck_fontes_nome_vazio
        CHECK (btrim(fte_nome) <> ''),

    CONSTRAINT ck_fontes_ordem_edicao
        CHECK (fte_ordem_edicao IN ('DATA', 'VERSAO'))
);

CREATE INDEX ix_fontes_ativa
    ON catalogo.fontes (fte_ativa, fte_codigo);

-- Seed inline — fontes de preços do tenant.
-- IDs canônicos do catálogo base:
--   AXYS=1 · SINAPI=2 · CDHU=3 · FDE=4
--   fte_ordem_edicao: 'DATA' = mais recente é maior edi_mes_ref;
--                     'VERSAO' = mais recente é maior edi_codigo_versao.
--   fte_tem_catalogo_insumos: SINAPI publica fichas de insumo; CDHU/FDE/AXYS não.
--   fte_tem_caderno_metodologia: SINAPI, CDHU e FDE publicam cadernos/livros técnicos; AXYS não.
--   fte_catalogos_continuos:  SINAPI traz data de atualização (skip por data); CDHU/FDE reemitem
--                             por edição; AXYS é app-own (contínuo).
--   fte_permite_manipular_dados: SÓ AXYS (fonte própria) = TRUE; terceiros = FALSE (imutáveis).
INSERT INTO catalogo.fontes (fte_id, fte_codigo, fte_nome, fte_ordem_edicao,
                             fte_tem_catalogo_insumos, fte_tem_caderno_metodologia,
                             fte_catalogos_continuos, fte_permite_manipular_dados, fte_public, fte_criado_por)
SELECT v.id, v.codigo, v.nome, v.ordem, v.tem_ins, v.tem_met, v.continuos, v.manipula, v.publico, 'Axys — seed inicial'
FROM (VALUES
    (1, 'AXYS',   'Composições Próprias',                               'DATA',   FALSE, FALSE, TRUE,  TRUE,  TRUE),
    (2, 'SINAPI', 'Sistema Nacional de Pesquisa de Custos e Índices da Construção Civil', 'DATA', TRUE, TRUE, TRUE, FALSE, TRUE),
    (3, 'CDHU',   'Companhia de Desenvolvimento Habitacional e Urbano', 'VERSAO', FALSE, TRUE, FALSE, FALSE, FALSE),
    (4, 'FDE',    'Fundação para o Desenvolvimento da Educação',        'DATA',   FALSE, TRUE, FALSE, FALSE, FALSE)
) AS v(id, codigo, nome, ordem, tem_ins, tem_met, continuos, manipula, publico)
ON CONFLICT (fte_codigo) DO UPDATE
    SET fte_id             = EXCLUDED.fte_id,
        fte_nome           = EXCLUDED.fte_nome,
        fte_ordem_edicao   = EXCLUDED.fte_ordem_edicao,
        fte_tem_catalogo_insumos = EXCLUDED.fte_tem_catalogo_insumos,
        fte_tem_caderno_metodologia = EXCLUDED.fte_tem_caderno_metodologia,
        fte_catalogos_continuos  = EXCLUDED.fte_catalogos_continuos,
        fte_permite_manipular_dados = EXCLUDED.fte_permite_manipular_dados,
        fte_public         = EXCLUDED.fte_public,
        fte_atualizado_em  = CURRENT_TIMESTAMP,
        fte_atualizado_por = 'Axys — seed inicial';
SELECT setval(
    pg_get_serial_sequence('catalogo.fontes', 'fte_id'),
    (SELECT COALESCE(MAX(fte_id), 1) FROM catalogo.fontes),
    true
);


-- ============================================================
-- TABELA: catalogo.edicoes
-- Contrato funcional (canônico):
--   docs/projects/axys-easy/contracts/catalogo/edicoes.md
-- Cada publicação de uma fonte de preços.
--
-- edi_mes_ref:       1º dia do mês de referência (DATE).
-- edi_codigo_versao: rótulo da edição.
--   Fonte VERSAO (CDHU) → nº do boletim ('184'..'201'); usado também p/ ordenar.
--   Fonte DATA (SINAPI) → rótulo MM-YY do boletim mensal ('08-24'); ordena por edi_mes_ref.
-- edi_uf_padrao:     UF exibida por padrão na consulta.
--   SINAPI: 'SP' — todas 27 UFs estão importadas na edição.
--   CDHU:   'SP' — fonte estadual, apenas SP.
--   FDE:    'SP' — fonte estadual, apenas SP.
-- edi_situacao_ciclo: estado único da edição (BUSINESS_RULES §10) — substitui o antigo
--   par ciclo+edi_ativa (que se sobrepunham). Enum:
--     'RASCUNHO'   = em construção/import; indisponível (nada usa ainda); editável.
--     'PUBLICADA'  = liberada (gates ok); disponível p/ uso novo E histórico; TRAVADA/imutável.
--     'EM_REVISAO' = só pós-PUBLICADA, se houver recall/correção: edição REABERTA (mutável p/
--                    o staff aplicar a correção), mas SEGUE disponível ao tenant como a PUBLICADA,
--                    com AVISO de revisão (e o que será revisado, em edi_revisao_nota). Concluída,
--                    volta a 'PUBLICADA'.
--     'ARQUIVADA'  = descontinuada p/ NOVOS usos; histórico e usos existentes permanecem;
--                    imutável (raro). NÃO é "indisponível" — só não inicia coisas novas.
--   "Disponível para novo uso" := edi_situacao_ciclo IN ('PUBLICADA','EM_REVISAO').
--   "Acessível (histórico)"     := edi_situacao_ciclo IN ('PUBLICADA','EM_REVISAO','ARQUIVADA').
--   Travadas (imutáveis): 'PUBLICADA' e 'ARQUIVADA'. Mutáveis: 'RASCUNHO' e 'EM_REVISAO'.
--   Botão "Publicar" valida os gates abaixo (RASCUNHO→PUBLICADA). Lock na camada app, sem trigger.
-- edi_revisao_nota: texto opcional exibido ao tenant quando 'EM_REVISAO' (o que será revisado).
-- edi_ins_catalogo_ok / edi_comp_catalogo_ok: gates de upload de catálogo de DOCS (R2)
--   p/ poder publicar — fichas de insumo (auto-TRUE se fte_tem_catalogo_insumos=false) e
--   cadernos/critérios (obrigatório). Ver BUSINESS_RULES §10/§11.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.edicoes (
    edi_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    edi_fte_id         INTEGER NOT NULL,
    edi_mes_ref        DATE    NOT NULL,
    edi_codigo_versao  TEXT,
    edi_uf_padrao      CHAR(2) NOT NULL DEFAULT 'SP',
    -- Estado único do ciclo de vida (BUSINESS_RULES §10) — ver comentário acima.
    -- RASCUNHO (default) → PUBLICADA → EM_REVISAO ⇄ PUBLICADA · ARQUIVADA (raro).
    -- NÃO há mais edi_ativa (sobreposição removida).
    edi_situacao_ciclo  TEXT    NOT NULL DEFAULT 'RASCUNHO',
    edi_revisao_nota    TEXT,   -- o que será revisado (exibido ao tenant quando EM_REVISAO)
    edi_ins_catalogo_ok  BOOLEAN NOT NULL DEFAULT FALSE,  -- fichas de insumo no R2 (auto-TRUE se fonte sem catálogo de insumos)
    edi_comp_catalogo_ok BOOLEAN NOT NULL DEFAULT FALSE,  -- cadernos/critérios no R2 (obrigatório p/ publicar)
    -- Resolução de documentos da edição (preenchido pelo IMPORT): por tipo de doc, o estado
    --   'ok' (doc vigente obtido) | 'indisponivel' (declarado no form OU não obtido — link morto).
    --   Tipos: metodologia, calculos, notas, cadernos, fichas. "Disponível para publicação" :=
    --   dados importados E todo tipo EXIGIDO pela fonte resolvido (ok|indisponivel). Publicar
    --   avisa+permite quando há 'indisponivel'. Ver CONTRATO IMPORT §8 / BUSINESS_RULES §10.
    edi_docs_status      JSONB,
    -- Pipeline de IMPORT desmembrado em 4 estágios (Preparar→Preços→Dados→Documentos). NÃO confundir
    -- com edi_docs_status (resolução de docs por tipo, acima). Shape por estágio:
    --   { "<nome>": { "estado": <e>, "job_id": <str?>, "em": <iso8601?>, "detalhe": <obj?> } }
    --   nomes: preparar | precos | dados | documentos (nesta ordem).
    --   estados: locked (travado) | pronto (destravado, pode rodar) | rodando | ok | erro |
    --            pendente_user (só 'precos' — modal Informar dado / Publicar sem preço).
    --   Cascata: estágio N vira locked→pronto quando N-1 == ok; 'documentos'==ok → edição disponível
    --   p/ publicar. Ver CONTRATO catalogo/imports/estagios.md. NULL = ainda não iniciado (default no back).
    edi_estagios         JSONB,
    -- edi_capa_path — ⚠️ REMOVIDA 2026-07-15 (coluna MORTA: 0 read/write no código). A apresentação
    --   e o caderno da edição vivem em catalogo.documentos (doc_tipo='apresentacao'/'caderno_tecnico',
    --   por edição). O rebuild recria SEM ela; no banco vivo é dead-column inócua até o próximo rebuild.
    -- edi_paths: ÍNDICE dos artefatos de estado da edição — fronteira de governança do ESTADO
    -- (como catalogo.documentos é a fronteira dos DOCS). Mapa tipo→{path, resumo} dos JSONs no storage:
    --   { "status_estagios": {"path": "_state/estagios.json"},
    --     "links_edicao":    {"path": "_state/links.json"},
    --     "pendencias": { "<amarra>": {"path": "...", "abertas": <int>, "resumo": <str?>} } }
    --   amarras: unidades | mdo_h_mes | mo_fte_sinapi | subst_ins | subst_cmp (Vinculações Intra-Fontes).
    --   GATE GENÉRICO de publicação/caderno: exige TODA pendencias.<amarra>.abertas == 0
    --   ("revisado ≠ vinculado": 'sem_equivalente' fecha; só delta pendente trava). Substitui o gate
    --   hardcoded de unidades. Escrito SEMPRE via helper registrar_artefato (grava o JSON + indexa aqui
    --   na MESMA transação → nunca dessincroniza). Contrato: vinculacoes.md.
    edi_paths            JSONB,
    edi_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    edi_atualizado_em  TIMESTAMPTZ,
    edi_criado_por     TEXT,
    edi_atualizado_por TEXT,

    CONSTRAINT fk_edicoes_fte
        FOREIGN KEY (edi_fte_id)
        REFERENCES catalogo.fontes (fte_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT uq_edicoes_fte_mes
        UNIQUE (edi_fte_id, edi_mes_ref),

    CONSTRAINT ck_edicoes_primeiro_do_mes
        CHECK (EXTRACT(DAY FROM edi_mes_ref) = 1),

    CONSTRAINT ck_edicoes_codigo_versao_vazio
        CHECK (edi_codigo_versao IS NULL OR btrim(edi_codigo_versao) <> ''),

    CONSTRAINT ck_edicoes_situacao_ciclo
        CHECK (edi_situacao_ciclo IN ('RASCUNHO', 'PUBLICADA', 'EM_REVISAO', 'ARQUIVADA'))
);

CREATE INDEX ix_edicoes_fte_mes
    ON catalogo.edicoes (edi_fte_id, edi_mes_ref DESC);

-- Lookup rápido das edições disponíveis p/ novo uso (substitui ix_edicoes_ativas).
-- Disponível := PUBLICADA ∪ EM_REVISAO (EM_REVISAO segue disponível ao tenant, com aviso).
CREATE INDEX ix_edicoes_disponiveis
    ON catalogo.edicoes (edi_fte_id, edi_mes_ref DESC)
    WHERE edi_situacao_ciclo IN ('PUBLICADA', 'EM_REVISAO');

-- Seed inline — trilha histórica de edições (FONTE ÚNICA). Reconstruída do zero:
-- dropa as atuais, reinicia a IDENTITY e reinsere AGRUPADO POR FONTE, na ordem:
-- SINAPI → CDHU → FDE. O ORDER BY abaixo garante essa sequência de edi_id.
-- Depende do seed de catalogo.fontes acima.
--   SINAPI: fonte DATA   → edi_codigo_versao = rótulo MM-YY do boletim mensal ('08-24'..'05-26').
--   CDHU:   fonte VERSAO → edi_codigo_versao = nº do boletim ('184'..'201'); mono-UF SP.
--   FDE:    fonte DATA   → rótulo MM-YY das edições trimestrais ('07-22'..'04-26'); mono-UF SP.
DELETE FROM catalogo.edicoes;
ALTER TABLE catalogo.edicoes ALTER COLUMN edi_id RESTART WITH 1;

INSERT INTO catalogo.edicoes (edi_fte_id, edi_mes_ref, edi_codigo_versao, edi_uf_padrao, edi_criado_por)
SELECT f.fte_id, v.mes::DATE, v.versao, 'SP', 'Axys — seed inicial'
FROM (VALUES
    -- SINAPI 08/2024→04/2026 (boletim mensal, uma edição por mês)
    ('SINAPI', '2024-08-01', '08-24'),
    ('SINAPI', '2024-09-01', '09-24'),
