-- ============================================================
-- TABELA: catalogo.sinapi_manutencoes
-- Contrato de regra de negócio (canônico):
--   docs/projects/axys-easy/contracts/catalogo/imports/sinapi.md
-- Log de alterações do SINAPI por boletim mensal.
-- Referência para rastrear o que mudou entre edições.
-- Imutável após import.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.sinapi_manutencoes (
    sm_id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sm_edi_id       INTEGER NOT NULL,
    sm_tipo         TEXT    NOT NULL,
    sm_codigo       TEXT    NOT NULL,
    sm_descricao    TEXT,
    sm_manutencao   TEXT    NOT NULL,
    sm_importado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_sm_edi
        FOREIGN KEY (sm_edi_id)
        REFERENCES catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT ck_sm_tipo
        CHECK (sm_tipo IN ('INSUMO', 'COMPOSICAO'))
);

CREATE INDEX ix_sm_edi
    ON catalogo.sinapi_manutencoes (sm_edi_id);

CREATE INDEX ix_sm_codigo
    ON catalogo.sinapi_manutencoes (sm_codigo, sm_edi_id);

CREATE INDEX ix_sm_manutencao
    ON catalogo.sinapi_manutencoes (sm_manutencao);


-- ============================================================
-- TABELA: catalogo.insumos_equivalencias
-- [família §EQUIVALÊNCIAS E CONVERSÕES — ver banner antes de composicoes_mapeamento_mdo]
-- Papel: mapa DIFUSO insumo↔insumo (score/tipo). SUGERE; não aplica swap.
-- Equivalência entre insumos de fontes-base diferentes (ex.: insumo
-- CDHU ≈ insumo SINAPI). Implementada na origem (import).
-- ie_tipo_equivalencia: EXATA | APROXIMADA | SUBSTITUTA |
--   COMERCIAL | SEMANTICA.   ie_score: confiança 0..1.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.insumos_equivalencias (
    ie_id                  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ie_ins_id_origem       BIGINT NOT NULL,
    ie_ins_id_equivalente  BIGINT NOT NULL,
    ie_tipo_equivalencia   TEXT,
    ie_score               NUMERIC(4,3),
    ie_metodo              TEXT,
    ie_observacao          TEXT,
    ie_ativo               BOOLEAN NOT NULL DEFAULT TRUE,
    ie_criado_em           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ie_atualizado_em       TIMESTAMPTZ,
    ie_criado_por          TEXT,
    ie_atualizado_por      TEXT,

    CONSTRAINT fk_insumos_equivalencias_origem
        FOREIGN KEY (ie_ins_id_origem)
        REFERENCES catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_insumos_equivalencias_equivalente
        FOREIGN KEY (ie_ins_id_equivalente)
        REFERENCES catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT ck_insumos_equivalencias_nao_auto
        CHECK (ie_ins_id_origem <> ie_ins_id_equivalente),

    CONSTRAINT ck_insumos_equivalencias_tipo
        CHECK (ie_tipo_equivalencia IS NULL OR ie_tipo_equivalencia IN
            ('EXATA', 'APROXIMADA', 'SUBSTITUTA', 'COMERCIAL', 'SEMANTICA')),

    CONSTRAINT ck_insumos_equivalencias_score
        CHECK (ie_score IS NULL OR (ie_score >= 0 AND ie_score <= 1))
);

CREATE INDEX ix_insumos_equivalencias_origem
    ON catalogo.insumos_equivalencias (ie_ins_id_origem);
CREATE INDEX ix_insumos_equivalencias_equivalente
    ON catalogo.insumos_equivalencias (ie_ins_id_equivalente);


-- ============================================================
-- TABELA: catalogo.insumos_historico
-- Trilha de auditoria da EVOLUÇÃO CADASTRAL do insumo ao longo das
-- edições da fonte-base (criação, alteração de descrição/unidade/
-- tipo/classificação, inativação, reativação). Implementada na origem.
--
-- NÃO armazena preços e NÃO substitui catalogo.insumos_preco (série
-- histórica de preços por edição/UF/modalidade). catalogo.insumos
-- continua representando o ESTADO VIGENTE; esta tabela guarda o
-- histórico documental.
--
-- ih_tipo_evento: CRIACAO | ALTERACAO | INATIVACAO | REATIVACAO.
-- ih_edi_id_inicio / ih_edi_id_fim: faixa de edições (fim NULL = aberto).
-- JSONB intencional: o conjunto de campos alterados varia por
--   fonte-base/versão — snapshot/diff documental.
-- Append-only: sem _atualizado_* (snapshots imutáveis).
--
-- ESTRUTURA RECOMENDADA dos JSONB (NÃO contrato rígido — pode variar
--   conforme fonte-base, parser e tipo de alteração):
--   CRIACAO    → ih_dados_novos {edicao, codigo, descricao, unidade, tipo, ativo}
--   ALTERACAO  → ih_dados_anteriores {edicao_origem, descricao, unidade, tipo, ativo};
--                ih_dados_novos {edicao_alteracao, descricao, unidade, tipo, ativo};
--                ih_diff {descricao:{de,para}, unidade:{de,para}}  (só os mudados)
--   INATIVACAO → ih_dados_anteriores {ultima_edicao_ativa, codigo, ..., ativo:true};
--                ih_dados_novos {edicao_inativacao, ativo:false};
--                ih_diff {ativo:{de:true, para:false}}
--   REATIVACAO → simétrico (edicao_reativacao; ativo:{de:false, para:true})
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.insumos_historico (
    ih_id                INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ih_ins_id            BIGINT NOT NULL,
    ih_edi_id_inicio     INTEGER,
    ih_edi_id_fim        INTEGER,
    ih_tipo_evento       TEXT    NOT NULL,
    ih_dados_anteriores  JSONB,
    ih_dados_novos       JSONB,
    ih_diff              JSONB,
    ih_observacao        TEXT,
    ih_criado_em         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ih_criado_por        TEXT,

    CONSTRAINT fk_insumos_historico_ins
        FOREIGN KEY (ih_ins_id)
        REFERENCES catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_insumos_historico_edi_inicio
        FOREIGN KEY (ih_edi_id_inicio)
        REFERENCES catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_insumos_historico_edi_fim
        FOREIGN KEY (ih_edi_id_fim)
        REFERENCES catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT ck_insumos_historico_tipo_evento
        CHECK (ih_tipo_evento IN
            ('CRIACAO', 'ALTERACAO', 'INATIVACAO', 'REATIVACAO'))
);

CREATE INDEX ix_insumos_historico_ins
    ON catalogo.insumos_historico (ih_ins_id);
CREATE INDEX ix_insumos_historico_ins_edi
    ON catalogo.insumos_historico (ih_ins_id, ih_edi_id_inicio);
CREATE INDEX ix_insumos_historico_tipo
    ON catalogo.insumos_historico (ih_tipo_evento);
CREATE INDEX ix_insumos_historico_diff
    ON catalogo.insumos_historico USING GIN (ih_diff);


-- ============================================================
-- ============================================================
--   EXPANSÃO FUTURA — RESERVAS ESTRUTURAIS (não usadas no MVP v1)
-- ============================================================
-- As estruturas abaixo são PREVISÃO de expansão. Existem para
-- deixar o banco escalável — taxonomia/ontologia de insumos,
-- atributos técnicos, códigos externos (NCM/EAN/CATMAT/CATSER/
-- fabricante), pesquisa de preço por NF-e pública (Lei Federal
-- 14.133) e auditoria/evolução histórica de composições — SEM
-- contaminar a regra de negócio inicial.
--
-- NÃO usar como regra de negócio no MVP v1. NÃO serão populadas
-- na primeira versão. Sem parser, carga, integração ou tela ainda.
-- catalogo.insumos continua sendo a identidade principal do insumo,
-- vinculada à sua fonte-base.
-- ============================================================
-- ============================================================


-- ============================================================
-- TABELA: catalogo.insumos_classificacao   [EXPANSÃO FUTURA]
-- Classificação semântica/técnica do insumo — relacional e
-- consultável (sem JSONB). Ex.: família 'tubo pvc', subfamília
-- 'tubo pvc esgoto', categoria 'instalações hidrossanitárias',
-- especificação 'DN 100 mm, série normal', unidade norm. 'barra'.
-- Reserva estrutural — não populada no MVP v1.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.insumos_classificacao (
    ic_id                  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ic_ins_id              BIGINT NOT NULL,
    ic_familia             TEXT,
    ic_subfamilia          TEXT,
    ic_categoria           TEXT,
    ic_especificacao       TEXT,
    ic_unidade_normalizada TEXT,
    ic_criado_em           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ic_atualizado_em       TIMESTAMPTZ,
    ic_criado_por          TEXT,
    ic_atualizado_por      TEXT,

    CONSTRAINT fk_insumos_classificacao_ins
        FOREIGN KEY (ic_ins_id)
        REFERENCES catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE INDEX ix_insumos_classificacao_ins
    ON catalogo.insumos_classificacao (ic_ins_id);


-- ============================================================
-- TABELA: catalogo.insumos_atributos   [EXPANSÃO FUTURA]
-- Atributos técnicos parametrizados — modelo EAV controlado,
-- relacional (sem JSONB). Ex.: (diametro, 100, mm),
-- (classe, esgoto, NULL), (comprimento, 6, m), (material, PVC, NULL).
-- Reserva estrutural — não populada no MVP v1.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.insumos_atributos (
    ia_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ia_ins_id          BIGINT NOT NULL,
    ia_atributo        TEXT    NOT NULL,
    ia_valor           TEXT,
    ia_unidade         TEXT,
    ia_ordem           INTEGER,
    ia_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ia_atualizado_em   TIMESTAMPTZ,
    ia_criado_por      TEXT,
    ia_atualizado_por  TEXT,

    CONSTRAINT fk_insumos_atributos_ins
        FOREIGN KEY (ia_ins_id)
        REFERENCES catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT ck_insumos_atributos_atributo_vazio
        CHECK (btrim(ia_atributo) <> '')
);

CREATE INDEX ix_insumos_atributos_ins
    ON catalogo.insumos_atributos (ia_ins_id);
CREATE INDEX ix_insumos_atributos_atributo
    ON catalogo.insumos_atributos (ia_atributo);


-- ============================================================
-- TABELA: catalogo.insumos_codigos_externos   [EXPANSÃO FUTURA]
-- Vínculo do insumo a códigos externos / fiscais / comerciais.
-- Um insumo pode ter VÁRIOS códigos de tipos diferentes — por isso
-- é tabela, não colunas fixas (ncm/ean/...) em catalogo.insumos.
-- ice_tipo_codigo: NCM | EAN | GTIN | CATMAT | CATSER | FABRICANTE
--   | OUTRO.
-- Reserva estrutural — não populada no MVP v1.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.insumos_codigos_externos (
    ice_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ice_ins_id         BIGINT NOT NULL,
    ice_tipo_codigo    TEXT    NOT NULL,
    ice_codigo         TEXT    NOT NULL,
    ice_descricao      TEXT,
    ice_fonte          TEXT,
    ice_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ice_atualizado_em  TIMESTAMPTZ,
    ice_criado_por     TEXT,
    ice_atualizado_por TEXT,

    CONSTRAINT fk_insumos_codigos_externos_ins
        FOREIGN KEY (ice_ins_id)
        REFERENCES catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT ck_insumos_codigos_externos_tipo
        CHECK (ice_tipo_codigo IN
            ('NCM', 'EAN', 'GTIN', 'CATMAT', 'CATSER', 'FABRICANTE', 'OUTRO')),

    CONSTRAINT ck_insumos_codigos_externos_codigo_vazio
        CHECK (btrim(ice_codigo) <> '')
);

CREATE INDEX ix_insumos_codigos_externos_ins
    ON catalogo.insumos_codigos_externos (ice_ins_id);
CREATE INDEX ix_insumos_codigos_externos_tipo_codigo
    ON catalogo.insumos_codigos_externos (ice_tipo_codigo, ice_codigo);


-- ============================================================
-- TABELA: catalogo.insumos_nfe_itens_precos   [EXPANSÃO FUTURA]
-- Preços derivados de itens de NF-e — pesquisa de preço por nota
-- fiscal eletrônica (Lei 14.133). O mapeamento ao catálogo é
-- opcional (nip_ins_id_mapeado NULLABLE), podendo vir de matching
-- semântico. Representação relacional, sem JSONB.
-- Fica em catalogo (mesmo schema de insumos_preco) — sem schema
-- 'precos' separado. Reserva estrutural — não populada no MVP v1.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.insumos_nfe_itens_precos (
    nip_id                  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nip_ins_id_mapeado      BIGINT,
    nip_chave_nfe           TEXT,
    nip_data_emissao        DATE,
    nip_uf                  TEXT,
    nip_municipio           TEXT,
    nip_cnpj_emitente_hash  TEXT,
    nip_descricao_original  TEXT,
    nip_ncm                 TEXT,
    nip_ean                 TEXT,
    nip_unidade             TEXT,
    nip_quantidade          NUMERIC(14,4),
    nip_valor_unitario      NUMERIC(14,4),
    nip_valor_total         NUMERIC(14,4),
    nip_score_mapeamento    NUMERIC(4,3),
    nip_metodo_mapeamento   TEXT,
    nip_criado_em           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_insumos_nfe_itens_precos_ins
        FOREIGN KEY (nip_ins_id_mapeado)
        REFERENCES catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT ck_insumos_nfe_itens_precos_score
        CHECK (nip_score_mapeamento IS NULL
               OR (nip_score_mapeamento >= 0 AND nip_score_mapeamento <= 1))
);

CREATE INDEX ix_insumos_nfe_itens_precos_ins
    ON catalogo.insumos_nfe_itens_precos (nip_ins_id_mapeado)
    WHERE nip_ins_id_mapeado IS NOT NULL;
CREATE INDEX ix_insumos_nfe_itens_precos_ncm
    ON catalogo.insumos_nfe_itens_precos (nip_ncm)
    WHERE nip_ncm IS NOT NULL;
CREATE INDEX ix_insumos_nfe_itens_precos_chave
    ON catalogo.insumos_nfe_itens_precos (nip_chave_nfe);


-- ============================================================
-- TABELA: catalogo.composicoes_historico   [FASE 2 — ATIVA]
-- SNAPSHOT-NA-MUDANÇA (esparso) da EVOLUÇÃO CADASTRAL/ESTRUTURAL das composições
-- (cabeçalho, receita, situação). É o mecanismo de retroação da Fase 2 (§9.6): o import
-- GRAVA um evento quando muda descrição/unidade/receita; get_historico_custos LÊ.
-- ch_dados_novos = snapshot completo "como era na edição E" (1 lookup, sem walk). O CUSTO
-- NUNCA entra aqui (vive em composicoes_custo). Append-only (sem _atualizado_*).
-- Nota: convenção temporal diferente de insumos_historico (evento origem/nova × faixa inicio/fim);
--   divergência ACEITA (ambas funcionam, as-of resolve). Alinhar é opcional, sem gatilho.
--
-- ch_tipo_evento: CRIACAO | ALTERACAO_CABECALHO | ALTERACAO_ITENS |
--   ALTERACAO_CABECALHO_E_ITENS | INATIVACAO | REATIVACAO |
--   ALTERACAO_SITUACAO | ALTERACAO_CUSTO_FONTE |
--   ALTERACAO_CUSTO_CALCULADO | DIVERGENCIA_CUSTO.
-- JSONB INTENCIONAL: o conjunto de alterações estruturais varia muito
--   entre edições (snapshot/diff documental). Append-only (sem _atualizado_*).
--
-- ESTRUTURA RECOMENDADA do ch_diff por tipo (NÃO contrato rígido — pode
--   variar conforme fonte-base, parser e tipo de alteração):
--   ALTERACAO_CABECALHO → {cabecalho:{descricao:{de,para}, unidade:{de,para},
--                          situacao:{de,para}}}
--   ALTERACAO_ITENS     → {itens:{incluidos:[{tipo,codigo,descricao,unidade,
--                          coeficiente,situacao}], excluidos:[...],
--                          alterados:[{tipo,codigo,campo,de,para}]}}
--   ALTERACAO_SITUACAO  → {situacao:{de,para,motivo}, itens_criticos:[{tipo,
--                          codigo,descricao,situacao}]}
--   ALTERACAO_CUSTO_* / DIVERGENCIA_CUSTO → {custos:{uf, modalidade,
--                          custo_fonte:{de,para}, custo_calculado:{de,para},
--                          diferenca_valor:{de,para}, diferenca_percentual:{de,para},
--                          status_conferencia:{de,para}}}
--   ch_dados_anteriores / ch_dados_novos: snapshot do cabeçalho na edição
--                          origem / nova.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.composicoes_historico (
    ch_id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ch_cmp_id_origem    BIGINT,
    ch_cmp_id_novo      BIGINT,
    ch_fte_id           INTEGER NOT NULL,
    ch_codigo           TEXT    NOT NULL,
    ch_edi_id_origem    INTEGER,
    ch_edi_id_nova      INTEGER,
    ch_tipo_evento      TEXT    NOT NULL,
    ch_dados_anteriores JSONB,
    ch_dados_novos      JSONB,
    ch_diff             JSONB,
    ch_observacao       TEXT,
    ch_criado_em        TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ch_criado_por       TEXT,

    CONSTRAINT fk_composicoes_historico_cmp_origem
        FOREIGN KEY (ch_cmp_id_origem)
        REFERENCES catalogo.composicoes (cmp_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_composicoes_historico_cmp_novo
        FOREIGN KEY (ch_cmp_id_novo)
        REFERENCES catalogo.composicoes (cmp_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_composicoes_historico_fte
        FOREIGN KEY (ch_fte_id)
        REFERENCES catalogo.fontes (fte_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_composicoes_historico_edi_origem
        FOREIGN KEY (ch_edi_id_origem)
        REFERENCES catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_composicoes_historico_edi_nova
        FOREIGN KEY (ch_edi_id_nova)
        REFERENCES catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT ck_composicoes_historico_tipo_evento
        CHECK (ch_tipo_evento IN (
            'CRIACAO', 'ALTERACAO_CABECALHO', 'ALTERACAO_ITENS',
            'ALTERACAO_CABECALHO_E_ITENS', 'INATIVACAO', 'REATIVACAO',
            'ALTERACAO_SITUACAO', 'ALTERACAO_CUSTO_FONTE',
            'ALTERACAO_CUSTO_CALCULADO', 'DIVERGENCIA_CUSTO'
        ))
);

CREATE INDEX ix_composicoes_historico_fte_codigo
    ON catalogo.composicoes_historico (ch_fte_id, ch_codigo);
CREATE INDEX ix_composicoes_historico_edis
    ON catalogo.composicoes_historico (ch_edi_id_origem, ch_edi_id_nova);
CREATE INDEX ix_composicoes_historico_tipo
    ON catalogo.composicoes_historico (ch_tipo_evento);
CREATE INDEX ix_composicoes_historico_cmp_origem
    ON catalogo.composicoes_historico (ch_cmp_id_origem);
CREATE INDEX ix_composicoes_historico_cmp_novo
    ON catalogo.composicoes_historico (ch_cmp_id_novo);


-- ============================================================
-- TABELA: catalogo.composicoes_custo_alerta
-- Contrato de regra de negócio (canônico):
--   docs/projects/axys-easy/contracts/catalogo/listagem.md  (§4.2)
-- Alerta ENXUTO: só a CAUSA de um problema de custo/situação (item sem preço,
--   subcomposição sem custo, divergência relevante). NÃO repete custo — os
--   números (fonte/calculado/diferença/status) vivem em composicoes_custo, a um
--   JOIN via cca_cc_id. Persistido APENAS para casos relevantes (fila de revisão);
--   a causa item-a-item é derivável quando não persistida.
--
-- cca_cc_id:  linha de custo (cmp/uf/modalidade) à qual o alerta se refere.
-- cca_ci_id:  item culpado (nullable — alerta pode ser da composição inteira).
-- cca_tipo_alerta: ITEM_SEM_PRECO | SUBCOMPOSICAO_SEM_CUSTO |
--   COMPOSICAO_SEM_CUSTO | CUSTO_OFICIAL_ZERO | DIVERGENTE_RELEVANTE.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.composicoes_custo_alerta (
    cca_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cca_cc_id          BIGINT NOT NULL,
    cca_ci_id          BIGINT,
    cca_tipo_alerta    TEXT    NOT NULL,
    cca_observacao     TEXT,
    cca_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_composicoes_custo_alerta_cc
        FOREIGN KEY (cca_cc_id)
        REFERENCES catalogo.composicoes_custo (cc_id)
        ON UPDATE CASCADE ON DELETE CASCADE,

    CONSTRAINT fk_composicoes_custo_alerta_ci
        FOREIGN KEY (cca_ci_id)
        REFERENCES catalogo.composicoes_itens (ci_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT ck_composicoes_custo_alerta_tipo
        CHECK (cca_tipo_alerta IN (
            'ITEM_SEM_PRECO', 'SUBCOMPOSICAO_SEM_CUSTO', 'COMPOSICAO_SEM_CUSTO',
            'CUSTO_OFICIAL_ZERO', 'DIVERGENTE_RELEVANTE'
        ))
);

CREATE INDEX ix_composicoes_custo_alerta_cc
    ON catalogo.composicoes_custo_alerta (cca_cc_id);
CREATE INDEX ix_composicoes_custo_alerta_tipo
    ON catalogo.composicoes_custo_alerta (cca_tipo_alerta);


-- ============================================================
-- catalogo.documentos_origem / catalogo.documentos — REGISTRO central dos docs
-- de EDIÇÃO/FONTE SEM dono 1:1 (livros, metodologia, notas, cadernos-fonte PDF,
-- originais, apresentações, critério CDHU, LS, referências). FRONTEIRA DE
-- GOVERNANÇA: o import ESCREVE; a app e os "livros" LÊEM. Ver §11.9.
-- ⚠️ REVISTO 2026-07-13: ficha/caderno_cpu/CTC (SINAPI) NÃO ficam aqui — vivem na
-- IDENTIDADE (ins_external_path/cmp_external_path, vigência por versão §11.10),
-- que é a FONTE ÚNICA (não cache). Reverte o "unifica os JSONB" da fase 1.
--
-- documentos_origem: proveniência (arquivo da matriz Caixa — que pode sumir — +
--   cópia no R2/audit). Dedup por arquivo: muitos docs compartilham a mesma origem.
-- documentos: 1 linha por doc; FK p/ identidade (ins/cmp/sub/edi) e p/ origem.
--   doc_vigente = versão atual × histórico; doc_orfao = no R2 sem identidade
--   vigente (caderno documenta composição descontinuada/fora da edição).
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.documentos_origem (
    org_id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    org_fte_id     INTEGER NOT NULL REFERENCES catalogo.fontes(fte_id),
    org_tipo       TEXT NOT NULL,           -- caderno-pdf | fichas-pdf | xlsx | metodologia-pdf | criterio-pdf
    org_arquivo    TEXT NOT NULL,
    org_url_matriz TEXT,                     -- link na fonte matriz (Caixa) — governança (pode sumir)
    org_path_r2    TEXT,                     -- cópia de auditoria no R2
    org_sha1       TEXT,
    org_criado_em  TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_documentos_origem UNIQUE (org_fte_id, org_arquivo)
);

CREATE TABLE IF NOT EXISTS catalogo.documentos (
    doc_id        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    doc_fte_id    INTEGER NOT NULL REFERENCES catalogo.fontes(fte_id),
    doc_tipo      TEXT NOT NULL,            -- EDIÇÃO/FONTE: caderno(fonte)|caderno_tecnico|apresentacao|criterio(CDHU)|metodologia|livro|nota|leis_sociais|referencia|original|ficha_fonte(FDE)
                                            -- ⚠️ ficha/caderno_cpu/CTC (SINAPI) saíram p/ external_path (§11.9) — não escrever aqui.
    doc_ins_id    BIGINT REFERENCES catalogo.insumos(ins_id),
    doc_cmp_id    BIGINT REFERENCES catalogo.composicoes(cmp_id),
    doc_sub_id    INTEGER REFERENCES catalogo.composicoes_subgrupos(sub_id),
    doc_edi_id    INTEGER REFERENCES catalogo.edicoes(edi_id),
    doc_org_id    INTEGER REFERENCES catalogo.documentos_origem(org_id),
    doc_path      TEXT NOT NULL,
    doc_url       TEXT,
    doc_titulo    TEXT,                      -- p/ docs sem identidade (metodologia, planilhas, equip)
    doc_sha1      TEXT,
    doc_data      DATE,                      -- data do doc ("Atualizado em"/"Atualização")
    doc_versao    TEXT,                      -- edição PRÓPRIA do doc (livros têm edição independente
                                             -- da edição do catálogo). Compara livros: igual=skip,
                                             -- divergiu=arquiva _old + substitui. Ver CONTRATO IMPORT §8.
    doc_mime      TEXT,
    doc_vigente   BOOLEAN NOT NULL DEFAULT TRUE,
    doc_orfao     BOOLEAN NOT NULL DEFAULT FALSE,
    doc_is_public BOOLEAN NOT NULL DEFAULT FALSE,  -- BLINDAGEM AUTORAL: default RESTRITO. FALSE = não sobe
                                                   -- no caderno de user CLIENTE (perfil ≠ internal vê
                                                   -- "<acesso restrito>"); p/ user AXYS sobe. A flag do
                                                   -- import (por edição, default desmarcado) marca TRUE
                                                   -- só o que é de fonte pública (ex.: fichas FDE).
    doc_criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_documentos_path UNIQUE (doc_path)
);
CREATE INDEX IF NOT EXISTS ix_documentos_ins ON catalogo.documentos(doc_ins_id) WHERE doc_vigente;
CREATE INDEX IF NOT EXISTS ix_documentos_cmp ON catalogo.documentos(doc_cmp_id) WHERE doc_vigente;
CREATE INDEX IF NOT EXISTS ix_documentos_sub ON catalogo.documentos(doc_sub_id);
CREATE INDEX IF NOT EXISTS ix_documentos_fte_tipo ON catalogo.documentos(doc_fte_id, doc_tipo, doc_vigente);

-- ────────────────────────────────────────────────────────────────────────────
-- composicao_documento — ⚠️ DROPADA 2026-07-13 (repense doc/path, §11.9).
--   Existia só p/ religar caderno_cpu→composição, que já vive em cmp_external_path
--   (o doc próprio da composição = IDENTIDADE). Removida do schema (foto). A tabela
--   viva é dropada no rebuild (DROP TABLE IF EXISTS catalogo.composicao_documento).
--   Volta só se surgir cross-ref REAL (composição citando doc de OUTRA identidade);
--   o "Catálogo de Serviço/Componente" da AXYS Screen passa a ler de external_path.
-- ────────────────────────────────────────────────────────────────────────────


-- ============================================================
-- TABELAS: catalogo.indices + catalogo.indices_historico   — decisão Renan 2026-06-11
-- Índices econômicos (IGPM, IPCA, INCC, INPC, SELIC…) p/ sobrepor no gráfico de
-- evolução de preço (Histórico de Preços do insumo) — comparar a variação do
-- preço vs inflação/encargos, estilo "homebroker". O gráfico rebaseia tudo a 100
-- na data inicial; aqui guardamos o número-índice acumulado (e a variação % opcional).
-- `indices` = catálogo (PK natural = código legível, como catalogo.unidades);
-- `indices_historico` = série mensal (1 linha por índice × mês-ref).
-- FONTE ÚNICA da semente = o próprio serviço (não há script de seed): o botão "Atualizar
-- índices" da tela /indices e o beat noturno `catalogo.atualizar_indices` fazem bootstrap
-- quando a série está vazia e delta quando já há histórico. Duas famílias, em direções opostas:
--   • BCB/SGS (indices_service.INDICES) — a fonte dá a VARIAÇÃO % mensal e nós ACUMULAMOS o
--     número-índice base 100. Set: INCC-DI(192), IGP-M(189), IGP-DI(190), IPCA(433), INPC(188).
--     + a meta Selic (SGS 432) por caminho próprio: é TAXA (nível), não índice acumulável.
--   • IPOP/Fazenda-SP (indices_ipop.AGRUPAMENTOS) — 22 séries de obra pública (índice OFICIAL
--     de reajuste no Estado, Decreto 27.133). A fonte dá o NÚMERO-ÍNDICE publicado e a variação
--     é DERIVADA por LAG após gravar. Sem API: raspagem por postback ASP.NET.
-- Não há regra de negócio aqui — é dado de referência (re-rodar a atualização é idempotente).
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.indices (
    idc_codigo     TEXT PRIMARY KEY,            -- IGPM, IPCA, INCC, INPC, SELIC… (PK natural)
    idc_nome       TEXT NOT NULL,               -- "Índice Geral de Preços – Mercado"
    idc_fonte      TEXT,                         -- publicador (FGV, IBGE, BCB…)
    idc_ativo      BOOLEAN NOT NULL DEFAULT TRUE,
    idc_criado_em  TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Seed do CATÁLOGO de índices (get-or-create). O HISTÓRICO NÃO se semeia aqui: vem por api/curl
-- (BCB-SGS p/ INCC/IGP/IPCA/INPC/SELIC · IPOP FIPE/SEFAZ-SP p/ os IPOP-*), idempotente.
